create table public.finance_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,account_type text not null check(account_type in('CASH','BANK','RECEIVABLE')),is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),unique(tenant_id,name));create table public.finance_categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,category_type text not null check(category_type in('INCOME','EXPENSE')),is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),unique(tenant_id,name));create table public.finance_periods(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,starts_on date not null,ends_on date not null,is_closed boolean not null default false,created_at timestamptz not null default timezone('utc',now()),check(ends_on>=starts_on),unique(tenant_id,name));create table public.finance_settings(id uuid primary key default gen_random_uuid(),tenant_id uuid not null unique references public.tenants(id),currency_code text not null default 'IDR',invoice_prefix text not null default 'INV',receipt_prefix text not null default 'RCT',updated_at timestamptz not null default timezone('utc',now()));alter table public.finance_accounts enable row level security;alter table public.finance_categories enable row level security;alter table public.finance_periods enable row level security;alter table public.finance_settings enable row level security;revoke all on public.finance_accounts,public.finance_categories,public.finance_periods,public.finance_settings from anon,authenticated;create policy finance_accounts_tenant on public.finance_accounts for select to authenticated using(tenant_id=public.current_tenant_id());create policy finance_categories_tenant on public.finance_categories for select to authenticated using(tenant_id=public.current_tenant_id());create policy finance_periods_tenant on public.finance_periods for select to authenticated using(tenant_id=public.current_tenant_id());create policy finance_settings_tenant on public.finance_settings for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('finance_accounts.read','Read finance accounts','View finance accounts'),('finance_accounts.create','Create finance accounts','Create finance accounts'),('finance_accounts.update','Update finance accounts','Update finance accounts'),('finance_accounts.delete','Delete finance accounts','Delete finance accounts'),('finance_categories.read','Read finance categories','View finance categories'),('finance_categories.create','Create finance categories','Create finance categories'),('finance_categories.update','Update finance categories','Update finance categories'),('finance_categories.delete','Delete finance categories','Delete finance categories'),('finance_periods.read','Read finance periods','View finance periods'),('finance_periods.create','Create finance periods','Create finance periods'),('finance_periods.update','Update finance periods','Update finance periods'),('finance_periods.delete','Delete finance periods','Delete finance periods') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF') and (p.code like 'finance_accounts.%' or p.code like 'finance_categories.%' or p.code like 'finance_periods.%') on conflict do nothing;
